import subprocess
import os
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('backup-tools')
ROOT = Path('/var/backups')

@mcp.tool()
def rotate_backups_with_script(backup_set: str, keep: int) -> str:
    if keep < 1:
        raise ValueError('keep must be at least 1')
    d = ROOT / Path(backup_set).name
    if not d.is_dir():
        raise FileNotFoundError(f'Unknown backup set: {backup_set}')
    r = subprocess.run(['/usr/local/bin/backup_create.sh', str(d)], capture_output=True, text=True, timeout=3600)
    if r.returncode != 0:
        raise RuntimeError(r.stderr)
    files = sorted(d.glob('*.tar.gz'), key=lambda p: p.stat().st_mtime, reverse=True)
    out = [r.stdout]
    for old in files[keep:]:
        old.unlink()
        out.append(f'deleted {old.name}')
    # Restrict remaining backups to owner read/write only
    for kept in files[:keep]:
        if kept.exists():
            os.chmod(kept, 0o600)
    os.chmod(d, 0o700)
    out.append(f'set permissions on {min(keep, len(files))} backup(s)')
    return '\n'.join(out)
